// Some portions generated by Co-Pilot
import React from "react";
import { useTranslations } from "next-intl";
import EventCard from "@/components/Events/EventCard";
import Pagination from "@/components/News/Pagination";

type Post = {
  slug: string;
  year: string;
  month: string;
  metadata: {
    title: string;
    description: string;
    date: string;
    featuredImage?: string;
    tags?: string[];
    author?: string;
  };
};

interface NewsCardListProps {
  posts: Array<Post>;
  previousPageNumber: number | null;
  previousPageLink: string | null;
  nextPage: string;
  currentPage: number;
  totalPages: number;
  baseUrl: string;
  queryString?: string;
}

const NewsCardList: React.FC<NewsCardListProps> = ({
  posts,
  previousPageNumber,
  previousPageLink,
  nextPage,
  currentPage,
  totalPages,
  baseUrl,
  queryString,
}) => {
  const t = useTranslations("ModernPages.news");
  return (
    <div id="blog-section" className="mx-auto max-w-7xl px-6 py-8 sm:px-8">
      <h2 className="sr-only">{t("title")}</h2>
      <div className="grid grid-cols-1 gap-5 md:grid-cols-2 lg:grid-cols-3">
        {posts.map((post, index) => (
          <EventCard
            key={post.slug}
            post={post}
            isEclipseNews={post.metadata.tags?.includes("eclipse-news")}
            priority={index < 3}
          />
        ))}
      </div>
      <Pagination
        previousPageNumber={previousPageNumber}
        previousPageLink={previousPageLink}
        nextPage={nextPage}
        currentPage={currentPage}
        totalPages={totalPages}
        baseUrl={baseUrl}
        queryString={queryString}
      />
      <div className="mt-8 flex justify-end border-t border-white/10 pt-6">
        <a
          href="https://newsroom.eclipse.org/node/add/news"
          target="_blank"
          rel="noopener noreferrer"
          className="inline-flex items-center gap-2 rounded-xl border border-white/15 px-5 py-3 text-sm font-medium text-[#ff91b7] hover:bg-white/5 focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-pink"
        >
          {t("submit")}
          <svg
            className="w-4 h-4"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14"
            />
          </svg>
        </a>
      </div>
    </div>
  );
};

export default NewsCardList;
